import * as React from "react"
import { TrendingUpIcon, TrendingDownIcon, MinusIcon } from "lucide-react"

import { cn } from "@/lib/utils"
import { Badge } from "@/components/ui/badge"

// ── Shared types ─────────────────────────────────────────────────────────────

export type CardStatFormat = "currency" | "percent" | "integer" | "float"
export type CardStatTrend = "up" | "down" | "neutral"
export type CardStatSize = "sm" | "md" | "lg"

// ── Size tokens ───────────────────────────────────────────────────────────────

export const SIZE = {
  sm: {
    label: "text-xs font-medium tracking-wide uppercase",
    value: "text-xl font-semibold tracking-tight tabular-nums",
    description: "text-xs",
    headerIcon: "size-3.5",
    contentIcon: "size-4",
    badgeText: "text-xs font-semibold",
    badgeIcon: "size-2.5",
    badgePadding: "px-1.5 py-0.5",
    iconBox: "size-9 rounded-xl",
    iconInner: "size-4",
    highlightBox: "size-8 rounded-lg",
    highlightIcon: "size-4",
    highlightValue: "text-2xl font-semibold tracking-tight tabular-nums",
    highlightDesc: "text-xs",
    trackH: "h-2",
    gaugeMaxW: "max-w-[130px]",
    gaugeValue: "text-2xl font-semibold tracking-tight tabular-nums",
    listRowPy: "py-2",
    listText: "text-xs",
    listValue: "text-xs font-semibold tabular-nums",
    contentGap: "gap-2",
    compactValue: "text-lg font-semibold tracking-tight tabular-nums",
  },
  md: {
    label: "text-sm font-medium tracking-wide uppercase",
    value: "text-2xl font-semibold tracking-tight tabular-nums",
    description: "text-xs",
    headerIcon: "size-4",
    contentIcon: "size-5",
    badgeText: "text-xs font-semibold",
    badgeIcon: "size-3",
    badgePadding: "px-2 py-0.5",
    iconBox: "size-10 rounded-2xl",
    iconInner: "size-5",
    highlightBox: "size-9 rounded-xl",
    highlightIcon: "size-5",
    highlightValue: "text-3xl font-semibold tracking-tight tabular-nums",
    highlightDesc: "text-sm",
    trackH: "h-3",
    gaugeMaxW: "max-w-[160px]",
    gaugeValue: "text-3xl font-semibold tracking-tight tabular-nums",
    listRowPy: "py-2.5",
    listText: "text-sm",
    listValue: "text-sm font-semibold tabular-nums",
    contentGap: "gap-3",
    compactValue: "text-xl font-semibold tracking-tight tabular-nums",
  },
  lg: {
    label: "text-base font-medium tracking-wide uppercase",
    value: "text-3xl font-semibold tracking-tight tabular-nums",
    description: "text-sm",
    headerIcon: "size-5",
    contentIcon: "size-6",
    badgeText: "text-sm font-semibold",
    badgeIcon: "size-3.5",
    badgePadding: "px-2.5 py-1",
    iconBox: "size-12 rounded-2xl",
    iconInner: "size-6",
    highlightBox: "size-11 rounded-xl",
    highlightIcon: "size-6",
    highlightValue: "text-4xl font-semibold tracking-tight tabular-nums",
    highlightDesc: "text-base",
    trackH: "h-4",
    gaugeMaxW: "max-w-[200px]",
    gaugeValue: "text-4xl font-semibold tracking-tight tabular-nums",
    listRowPy: "py-3",
    listText: "text-base",
    listValue: "text-base font-semibold tabular-nums",
    contentGap: "gap-4",
    compactValue: "text-2xl font-semibold tracking-tight tabular-nums",
  },
} as const satisfies Record<CardStatSize, Record<string, string>>

// ── Shared helpers ────────────────────────────────────────────────────────────

export function formatValue(
  value: string | number,
  format?: CardStatFormat,
  opts?: { decimals?: number; locale?: string; currency?: string }
): string {
  if (!format || typeof value === "string") return String(value)
  const num = Number(value)
  const locale = opts?.locale ?? "en-US"
  const currency = opts?.currency ?? "USD"
  const decimals = opts?.decimals
  switch (format) {
    case "currency":
      return new Intl.NumberFormat(locale, {
        style: "currency",
        currency,
        minimumFractionDigits: decimals ?? 2,
        maximumFractionDigits: decimals ?? 2,
      }).format(num)
    case "percent":
      return (
        new Intl.NumberFormat(locale, {
          minimumFractionDigits: decimals ?? 1,
          maximumFractionDigits: decimals ?? 1,
        }).format(num) + "%"
      )
    case "integer":
      return new Intl.NumberFormat(locale, {
        minimumFractionDigits: 0,
        maximumFractionDigits: 0,
      }).format(num)
    case "float":
      return new Intl.NumberFormat(locale, {
        minimumFractionDigits: decimals ?? 2,
        maximumFractionDigits: decimals ?? 2,
      }).format(num)
  }
}

export const TREND_ICONS: Record<CardStatTrend, React.ElementType> = {
  up: TrendingUpIcon,
  down: TrendingDownIcon,
  neutral: MinusIcon,
}

export const TREND_COLORS: Record<CardStatTrend, string> = {
  up: "text-success",
  down: "text-destructive",
  neutral: "text-muted-foreground",
}

export function resolveTrend(
  trend: CardStatTrend | boolean | undefined
): CardStatTrend | false {
  if (trend === true) return "up"
  if (!trend) return false
  return trend
}

export interface FmtProps {
  format?: CardStatFormat
  decimals?: number
  locale?: string
  currency?: string
  valueFormatter?: (value: number | string) => string
}

export function applyFmt(value: number | string, opts: FmtProps): string {
  return opts.valueFormatter
    ? opts.valueFormatter(value)
    : formatValue(value, opts.format, {
        decimals: opts.decimals,
        locale: opts.locale,
        currency: opts.currency,
      })
}

// ── TrendBadge ────────────────────────────────────────────────────────────────

export function TrendBadge({
  trend,
  value,
  size = "md",
}: {
  trend: CardStatTrend
  value: string
  size?: CardStatSize
}) {
  const Icon = TREND_ICONS[trend]
  const s = SIZE[size]
  return (
    <Badge
      className={cn(
        s.badgePadding,
        s.badgeText,
        "font-semibold",
        trend === "up" && "bg-success/10 text-success",
        trend === "down" && "bg-destructive/10 text-destructive",
        trend === "neutral" && "bg-muted text-muted-foreground"
      )}
    >
      <Icon aria-hidden />
      {value}
    </Badge>
  )
}

// ── CardStatEmptySlot ─────────────────────────────────────────────────────────

export function CardStatEmptySlot({
  icon: Icon,
  message,
  sub,
  inverted = false,
}: {
  icon: React.ElementType
  message: string
  sub?: string
  inverted?: boolean
}) {
  return (
    <div className="flex flex-col items-center justify-center gap-2 py-5 text-center">
      <div
        className={cn(
          "flex size-9 items-center justify-center rounded-2xl",
          inverted ? "bg-white/15" : "bg-muted/60"
        )}
      >
        <Icon
          className={cn(
            "size-4",
            inverted ? "text-white/50" : "text-muted-foreground/50"
          )}
          aria-hidden
        />
      </div>
      <p
        className={cn(
          "text-xs font-medium",
          inverted ? "text-white/60" : "text-muted-foreground/70"
        )}
      >
        {message}
      </p>
      {sub && (
        <p
          className={cn(
            "text-xs leading-tight",
            inverted ? "text-white/40" : "text-muted-foreground/50"
          )}
        >
          {sub}
        </p>
      )}
    </div>
  )
}

import * as React from "react"

import { cn } from "@/lib/utils"
import { Card, CardAction, CardContent, CardHeader } from "@/components/ui/card"
import { Skeleton } from "@/components/ui/skeleton"

import {
  type CardStatTrend,
  type CardStatSize,
  type FmtProps,
  SIZE,
  applyFmt,
  resolveTrend,
  TrendBadge,
} from "./card-stats-shared"

function toSvgPts(
  data: number[],
  w: number,
  h: number,
  pad = 4
): [number, number][] {
  if (data.length < 2) return []
  const min = Math.min(...data)
  const max = Math.max(...data)
  const range = max - min || 1
  return data.map((v, i) => [
    pad + (i / (data.length - 1)) * (w - pad * 2),
    pad + (h - pad * 2) - ((v - min) / range) * (h - pad * 2),
  ])
}

function catmullRom(pts: [number, number][], tension = 0.4): string {
  if (pts.length < 2) return ""
  if (pts.length === 2)
    return `M ${pts[0][0]} ${pts[0][1]} L ${pts[1][0]} ${pts[1][1]}`
  let d = `M ${pts[0][0]} ${pts[0][1]}`
  for (let i = 0; i < pts.length - 1; i++) {
    const p0 = pts[Math.max(0, i - 1)]
    const p1 = pts[i]
    const p2 = pts[i + 1]
    const p3 = pts[Math.min(pts.length - 1, i + 2)]
    const cp1x = p1[0] + (p2[0] - p0[0]) * tension
    const cp1y = p1[1] + (p2[1] - p0[1]) * tension
    const cp2x = p2[0] - (p3[0] - p1[0]) * tension
    const cp2y = p2[1] - (p3[1] - p1[1]) * tension
    d += ` C ${cp1x.toFixed(1)} ${cp1y.toFixed(1)} ${cp2x.toFixed(1)} ${cp2y.toFixed(1)} ${p2[0].toFixed(1)} ${p2[1].toFixed(1)}`
  }
  return d
}

function SparklineSvg({
  data,
  width = 120,
  height = 44,
  trend,
}: {
  data: number[]
  width?: number
  height?: number
  trend?: CardStatTrend | boolean
}) {
  const id = React.useId()
  const dir = resolveTrend(trend)
  const stroke =
    dir === "up"
      ? "var(--color-success)"
      : dir === "down"
        ? "var(--color-destructive)"
        : "currentColor"

  const pts = toSvgPts(data, width, height)
  const line = catmullRom(pts)
  const last = pts[pts.length - 1]
  const first = pts[0]
  const area =
    pts.length >= 2
      ? `${line} L ${last[0]} ${height} L ${first[0]} ${height} Z`
      : ""

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      className="shrink-0 overflow-visible"
      aria-hidden
    >
      <defs>
        <linearGradient id={`sg-${id}`} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" style={{ stopColor: stroke }} stopOpacity="0.22" />
          <stop offset="100%" style={{ stopColor: stroke }} stopOpacity="0" />
        </linearGradient>
      </defs>
      {area && <path d={area} fill={`url(#sg-${id})`} />}
      {line && (
        <path
          d={line}
          fill="none"
          style={{ stroke }}
          strokeWidth="1.75"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      )}
      {last && (
        <circle cx={last[0]} cy={last[1]} r="2.5" style={{ fill: stroke }} />
      )}
    </svg>
  )
}

function FlatSparklineSvg({
  width = 120,
  height = 44,
}: {
  width?: number
  height?: number
}) {
  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      className="shrink-0 overflow-visible"
      aria-hidden
    >
      <line
        x1="4"
        y1={height / 2}
        x2={width - 4}
        y2={height / 2}
        stroke="currentColor"
        className="text-muted-foreground/25"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeDasharray="6 4"
      />
    </svg>
  )
}

export interface CardStatSparklineProps extends FmtProps {
  label: string
  value: string | number
  data?: number[]
  trend?: CardStatTrend | boolean
  trendValue?: string
  description?: string
  icon?: React.ElementType
  size?: CardStatSize
  className?: string
  loading?: boolean
  empty?: boolean
}

export function CardStatSparkline({
  label,
  value,
  data = [],
  trend,
  trendValue,
  description,
  icon: Icon,
  size = "md",
  className,
  loading,
  empty,
  ...fmt
}: CardStatSparklineProps) {
  const s = SIZE[size]
  const sparklineW = size === "sm" ? 90 : size === "lg" ? 150 : 120
  const sparklineH = size === "sm" ? 32 : size === "lg" ? 56 : 44

  if (loading) {
    return (
      <Card size="sm" className={className}>
        <CardHeader className="flex flex-row items-center justify-between">
          <Skeleton className="h-3 w-28 rounded-md" />
          <Skeleton className={cn(s.headerIcon, "rounded-md")} />
        </CardHeader>
        <CardContent className="flex items-end justify-between gap-4">
          <div className="flex flex-col gap-1.5">
            <Skeleton className="h-7 w-28" />
            <Skeleton className="h-5 w-24 rounded-full" />
          </div>
          <Skeleton
            className="rounded-xl"
            style={{ height: sparklineH, width: sparklineW }}
          />
        </CardContent>
      </Card>
    )
  }

  if (empty) {
    return (
      <Card size="sm" className={className}>
        <CardHeader className="flex flex-row items-center justify-between">
          <span className={cn("truncate text-muted-foreground", s.label)}>
            {label}
          </span>
          {Icon && (
            <CardAction className="text-muted-foreground">
              <Icon className={s.headerIcon} />
            </CardAction>
          )}
        </CardHeader>
        <CardContent className="flex items-end justify-between gap-4">
          <div className="flex flex-col gap-1.5">
            <p className={cn(s.value, "text-muted-foreground/25")}>—</p>
            <p className={cn("text-muted-foreground/40", s.description)}>
              No history yet
            </p>
          </div>
          <FlatSparklineSvg width={sparklineW} height={sparklineH} />
        </CardContent>
      </Card>
    )
  }

  const display = applyFmt(value, fmt)
  const trendDir = resolveTrend(trend)

  return (
    <Card size="sm" className={className}>
      <CardHeader className="flex flex-row items-center justify-between">
        <span className={cn("truncate text-muted-foreground", s.label)}>
          {label}
        </span>
        {Icon && (
          <CardAction className="text-muted-foreground">
            <Icon className={s.headerIcon} />
          </CardAction>
        )}
      </CardHeader>
      <CardContent className="flex items-end justify-between gap-4">
        <div className="flex flex-col gap-1.5">
          <p className={s.value}>{display}</p>
          {trendDir && trendValue ? (
            <TrendBadge trend={trendDir} value={trendValue} size={size} />
          ) : description ? (
            <p className={cn("text-muted-foreground", s.description)}>
              {description}
            </p>
          ) : null}
        </div>
        {data.length >= 2 && (
          <SparklineSvg
            data={data}
            trend={trend}
            width={sparklineW}
            height={sparklineH}
          />
        )}
      </CardContent>
    </Card>
  )
}

import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { BarChart2Icon } from "lucide-react"

import { cn } from "@/lib/utils"
import { Card, CardAction, CardContent, CardHeader } from "@/components/ui/card"
import { Skeleton } from "@/components/ui/skeleton"

import {
  type CardStatTrend,
  type CardStatSize,
  type FmtProps,
  SIZE,
  applyFmt,
  resolveTrend,
  TREND_ICONS,
  CardStatEmptySlot,
} from "./card-stats-shared"

export type CardStatHighlightVariant =
  | "primary"
  | "emerald"
  | "amber"
  | "rose"
  | "violet"
  | "sky"

export const cardStatHighlightVariants = cva(
  "relative overflow-hidden shadow-lg ring-0 dark:shadow-none",
  {
    variants: {
      variant: {
        primary: "bg-primary text-primary-foreground",
        emerald: "bg-success text-success-foreground",
        amber: "bg-warning text-warning-foreground",
        rose: "bg-destructive text-white",
        violet: "bg-highlight-violet text-highlight-violet-foreground",
        sky: "bg-highlight-sky text-highlight-sky-foreground",
      },
    },
    defaultVariants: { variant: "primary" },
  }
)

export interface CardStatHighlightProps
  extends FmtProps, VariantProps<typeof cardStatHighlightVariants> {
  label: string
  value: string | number
  description?: string
  trend?: CardStatTrend | boolean
  trendValue?: string
  icon?: React.ElementType
  size?: CardStatSize
  className?: string
  loading?: boolean
  empty?: boolean
}

export function CardStatHighlight({
  label,
  value,
  description,
  trend,
  trendValue,
  icon: Icon,
  variant = "primary",
  size = "md",
  className,
  loading,
  empty,
  ...fmt
}: CardStatHighlightProps) {
  const s = SIZE[size]

  const decorativeCircles = (
    <>
      <span
        aria-hidden
        className="pointer-events-none absolute -top-8 -right-8 size-32 rounded-full bg-white/10"
      />
      <span
        aria-hidden
        className="pointer-events-none absolute -right-4 -bottom-12 size-40 rounded-full bg-white/5"
      />
    </>
  )

  if (loading) {
    return (
      <Card size="sm" className={cn(cardStatHighlightVariants({ variant }), className)}>
        {decorativeCircles}
        <CardHeader className="relative flex flex-row items-start justify-between">
          <Skeleton className="h-3 w-24 bg-white/20" />
          <Skeleton className={cn(s.highlightBox, "bg-white/20")} />
        </CardHeader>
        <CardContent className="relative flex flex-col gap-2">
          <Skeleton className="h-9 w-40 bg-white/20" />
          <Skeleton className="h-5 w-32 bg-white/20" />
        </CardContent>
      </Card>
    )
  }

  if (empty) {
    return (
      <Card size="sm" className={cn(cardStatHighlightVariants({ variant }), className)}>
        {decorativeCircles}
        <CardHeader className="relative flex flex-row items-start justify-between">
          <span className={cn("opacity-75", s.label)}>{label}</span>
          {Icon && (
            <CardAction>
              <div
                className={cn(
                  "flex items-center justify-center bg-white/20",
                  s.highlightBox
                )}
              >
                <Icon className={s.highlightIcon} />
              </div>
            </CardAction>
          )}
        </CardHeader>
        <CardContent className="relative">
          <CardStatEmptySlot
            icon={BarChart2Icon}
            message="No spotlight yet"
            sub="Your headline KPI will appear here"
            inverted
          />
        </CardContent>
      </Card>
    )
  }

  const display = applyFmt(value, fmt)
  const trendDir = resolveTrend(trend)
  const TrendIcon = trendDir ? TREND_ICONS[trendDir] : null

  return (
    <Card size="sm" className={cn(cardStatHighlightVariants({ variant }), className)}>
      {decorativeCircles}

      <CardHeader className="relative flex flex-row items-start justify-between">
        <span className={cn("opacity-75", s.label)}>{label}</span>
        {Icon && (
          <CardAction>
            <div
              className={cn(
                "flex items-center justify-center bg-white/20",
                s.highlightBox
              )}
            >
              <Icon className={s.highlightIcon} />
            </div>
          </CardAction>
        )}
      </CardHeader>

      <CardContent className="relative flex flex-col gap-1.5">
        <p className={s.highlightValue}>{display}</p>
        {(trendDir || description) && (
          <p
            className={cn(
              "flex items-center gap-1.5 opacity-80",
              s.highlightDesc
            )}
          >
            {TrendIcon && (
              <TrendIcon
                className={cn(s.contentIcon, "shrink-0")}
                aria-hidden
              />
            )}
            {trendValue && <span className="font-semibold">{trendValue}</span>}
            {description && <span>{description}</span>}
          </p>
        )}
      </CardContent>
    </Card>
  )
}

import * as React from "react"
import { InboxIcon } from "lucide-react"

import { cn } from "@/lib/utils"
import { Card, CardAction, CardContent, CardHeader } from "@/components/ui/card"
import { Skeleton } from "@/components/ui/skeleton"

import {
  type CardStatTrend,
  type CardStatSize,
  type FmtProps,
  SIZE,
  applyFmt,
  resolveTrend,
  TREND_ICONS,
  CardStatEmptySlot,
} from "./card-stats-shared"

export interface CardStatListItem extends FmtProps {
  label: string
  value: string | number
  trend?: CardStatTrend | boolean
  trendValue?: string
}

export interface CardStatListProps {
  label: string
  items: CardStatListItem[]
  icon?: React.ElementType
  size?: CardStatSize
  className?: string
  loading?: boolean
  empty?: boolean
}

const SKELETON_ROW_WIDTHS = ["w-36", "w-28", "w-40", "w-32"] as const

export function CardStatList({
  label,
  items,
  icon: Icon,
  size = "md",
  className,
  loading,
  empty,
}: CardStatListProps) {
  const s = SIZE[size]

  if (loading) {
    return (
      <Card size="sm" className={className}>
        <CardHeader className="flex flex-row items-center justify-between">
          <Skeleton className="h-3 w-28 rounded-md" />
          <Skeleton className={cn(s.headerIcon, "rounded-md")} />
        </CardHeader>
        <CardContent className="p-0">
          <ul>
            {SKELETON_ROW_WIDTHS.map((w, i) => (
              <li
                key={i}
                className={cn(
                  "flex items-center justify-between gap-3 px-4",
                  s.listRowPy,
                  i !== 0 && "border-t border-border/50"
                )}
              >
                <Skeleton className={cn("h-3.5 rounded-md", w)} />
                <div className="flex shrink-0 items-center gap-2">
                  <Skeleton className="h-3.5 w-16 rounded-md" />
                  <Skeleton className="h-3.5 w-10 rounded-md" />
                </div>
              </li>
            ))}
          </ul>
        </CardContent>
      </Card>
    )
  }

  if (empty) {
    return (
      <Card size="sm" className={className}>
        <CardHeader className="flex flex-row items-center justify-between">
          <span className={cn("truncate text-muted-foreground", s.label)}>
            {label}
          </span>
          {Icon && (
            <CardAction className="text-muted-foreground">
              <Icon className={s.headerIcon} />
            </CardAction>
          )}
        </CardHeader>
        <CardContent>
          <CardStatEmptySlot
            icon={InboxIcon}
            message="List is empty"
            sub="Add metrics to start tracking"
          />
        </CardContent>
      </Card>
    )
  }

  return (
    <Card size="sm" className={className}>
      <CardHeader className="flex flex-row items-center justify-between">
        <span className={cn("truncate text-muted-foreground", s.label)}>
          {label}
        </span>
        {Icon && (
          <CardAction className="text-muted-foreground">
            <Icon className={s.headerIcon} />
          </CardAction>
        )}
      </CardHeader>
      <CardContent className="p-0">
        <ul>
          {items.map((item, i) => {
            const display = applyFmt(item.value, item)
            const trendDir = resolveTrend(item.trend)
            const TrendIcon = trendDir ? TREND_ICONS[trendDir] : null
            const trendCls =
              trendDir === "up"
                ? "text-success"
                : trendDir === "down"
                  ? "text-destructive"
                  : "text-muted-foreground"

            return (
              <li
                key={`${item.label}-${i}`}
                className={cn(
                  "flex items-center justify-between gap-3 px-4",
                  s.listRowPy,
                  "transition-colors hover:bg-muted/40",
                  i !== 0 && "border-t border-border/50"
                )}
              >
                <span
